"use client";

import { useState } from "react";

const serviceCenters = [
  {
    name: "boAt Service Center - Connaught Place",
    city: "New Delhi",
    address: "Delhi 110001",
    distance: "3.2 km"
  },
  {
    name: "boAt Service Center - Karol Bagh",
    city: "New Delhi",
    address: "Delhi 110005",
    distance: "5.7 km"
  },
  {
    name: "boAt Service Center - Dwarka",
    city: "New Delhi",
    address: "Delhi 110075",
    distance: "12.4 km"
  }
];

function ServiceCenterSearch() {
  const [city, setCity] = useState("");
  const [searched, setSearched] =
    useState(false);

  function handleSubmit(event) {
    event.preventDefault();

    setSearched(true);
  }

  const cityFound =
    city.trim().toLowerCase() === "delhi" ||
    city.trim().toLowerCase() === "new delhi";

  return (
    <div className="service-section">

      <div className="service-search">

        <h2>
          Find Service Center
        </h2>

        <p className="muted">
          Enter your city to find
          the nearest service centers.
        </p>

        <form
          onSubmit={handleSubmit}
          className="search"
        >

          <input
            value={city}
            onChange={(event) =>
              setCity(event.target.value)
            }
            placeholder="Enter your city"
          />

          <button
            type="submit"
            className="button"
          >
            Search
          </button>

        </form>

        {searched && !cityFound && (
          <div className="nearby-cities">

            <p>
              No service center in your city?
            </p>

            <p className="muted">
              Try these nearby cities:
            </p>

            <button
              onClick={() =>
                setCity("Gurugram")
              }
            >
              Gurugram
            </button>

            <button
              onClick={() =>
                setCity("Noida")
              }
            >
              Noida
            </button>

            <button
              onClick={() =>
                setCity("Faridabad")
              }
            >
              Faridabad
            </button>

          </div>
        )}

      </div>

      {searched && cityFound && (
        <div className="service-results">

          <h2>
            Nearest Service Centers
          </h2>

          {serviceCenters.map(
            (center) => (
              <div
                className="service-card"
                key={center.name}
              >

                <div>

                  <strong>
                    {center.name}
                  </strong>

                  <p>
                    {center.city},{" "}
                    {center.address}
                  </p>

                </div>

                <strong>
                  {center.distance}
                </strong>

              </div>
            )
          )}

        </div>
      )}

    </div>
  );
}

export default ServiceCenterSearch;